import type { commands } from "./bindings";

/** The full typed command surface generated by tauri-specta (`bindings.ts`). */
export type Commands = typeof commands;

export type Unlisten = () => void;

/**
 * Transport seam between the UI and the backend. The Tauri adapter forwards to `bindings.ts`;
 * the mock adapter serves in-memory sample data so the UI runs in a plain browser.
 */
export interface IpcAdapter {
  readonly kind: "tauri" | "mock";
  readonly commands: Commands;
  /** Subscribe to a backend event by name (`op://progress`, `menu://commit`, ...). */
  listen(name: string, handler: (payload: unknown) => void): Promise<Unlisten>;
}
